public void mapEntityToDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    TAMRebateDeal  rebateDeal;
    METIndustryKeyTable industryKeyTable;

    if (this.METIndustryKey)
    {
        select firstonly industryKeyTable
            where industryKeyTable.IndustryKey == this.METIndustryKey;

        if (industryKeyTable.RecId != 0)
        {
            ttsbegin;
            select forupdate rebateDeal
                where rebateDeal.Deal == this.DealNumber;
            if (rebateDeal.RecId != 0)
            {
                rebateDeal.METIndustryKeyId = industryKeyTable.RecId;
                rebateDeal.update();
            }
            ttscommit;
        }
    }

    next mapEntityToDataSource(_entityCtx, _dataSourceCtx);
}
